import React, { useState } from 'react';
import { ArrowUp, Check, X } from '@hexa-ui/icons';
import { Dropzone, FileValidated } from '@dropzone-ui/react';
import {
  Container,
  ImageContainer,
  IconContainer,
  ErrorContainer,
  IllustrationContainer,
} from './FileUploader.styles';
import { FileUploaderType } from './FileUploader.types';
import { DocumentImage } from './components/document-image';
import { FileImage } from './components/file-image';
import { Image } from './components/image';
import { Button } from '../button';
import { Heading, Paragraph } from '../typography';
import { Alert } from '../alert';
import { IconButtons } from './components/IconButtons/IconButtons';

const ImagesTypes = {
  document: DocumentImage,
  image: Image,
  file: FileImage,
};

const DEFAULT_TEXTS = {
  button: 'Browse Files',
};

const FileUploaderComponent = (
  {
    type = 'image',
    error,
    message,
    buttonIntl,
    imageHeight,
    imageFit = 'fill',
    value: valueFromProps,
    imageUrl,
    alt,
    ...props
  }: FileUploaderType,
  forwardedRef: React.ForwardedRef<HTMLDivElement>
): JSX.Element => {
  const [isHover, setIsHover] = useState<boolean>(false);
  const isControlled = valueFromProps !== undefined;
  const [value, setValue] = useState<FileValidated[]>([]);
  const mappedValue = isControlled ? valueFromProps : value;
  const hasValidFile = !!imageUrl || (!error && mappedValue.length > 0 && mappedValue?.[0].valid);

  const handleHover = () => setIsHover(true);
  const handleNotHover = () => setIsHover(false);
  const ImageComponent = ImagesTypes[type];

  const handleOnDrop = (filesDropped: FileValidated[]) => {
    if (props.onDrop) props.onDrop(filesDropped);
    setValue(filesDropped);
  };

  const handleOnClean = (event: React.MouseEvent<HTMLButtonElement>) => {
    event.stopPropagation();
    if (props.onClean) props.onClean(mappedValue);
    setValue([]);
  };

  return (
    <Dropzone
      {...props}
      style={{ border: 'none', width: '100%', minHeight: 'fit-content', borderRadius: '1rem' }}
      header={false}
      footer={false}
      maxFiles={1}
      onDrop={handleOnDrop}
    >
      {hasValidFile && type === 'image' ? (
        <Container
          type="validImage"
          css={{ height: imageHeight || '18.5625rem' }}
          ref={forwardedRef}
        >
          <ImageContainer
            src={imageUrl || URL.createObjectURL(mappedValue?.[0].file)}
            alt={alt || mappedValue[0].file.name}
            style={{ objectFit: imageFit }}
          />
          <IconButtons variant="image" handleOnClean={handleOnClean} elevation />
        </Container>
      ) : (
        <Container
          type={error ? 'error' : hasValidFile ? 'valid' : undefined}
          onMouseEnter={handleHover}
          onMouseLeave={handleNotHover}
          ref={forwardedRef}
        >
          {error && (
            <ErrorContainer>
              <Alert
                message={error.message}
                type="error"
                css={{ width: '100%' }}
                actions={error?.action ? [error.action] : undefined}
              />
            </ErrorContainer>
          )}
          <IllustrationContainer type={error ? 'error' : hasValidFile ? 'valid' : undefined}>
            <ImageComponent />
            <IconContainer type={error ? 'error' : hasValidFile ? 'valid' : undefined}>
              {error ? (
                <X size="xlarge" />
              ) : hasValidFile ? (
                <Check size="xlarge" />
              ) : (
                <ArrowUp size="xlarge" />
              )}
            </IconContainer>
          </IllustrationContainer>
          {hasValidFile ? (
            <>
              <Heading size="H2" alignment="center">
                {mappedValue[0].file.name}
              </Heading>
              <Paragraph
                alignment="center"
                colortype="secondary"
                size="small"
                css={{ lineHeight: '$5' }}
              >
                {Math.round(mappedValue[0].file.size / 1000)}kb
              </Paragraph>
              <IconButtons handleOnClean={handleOnClean} />
            </>
          ) : (
            <>
              <Paragraph size="small" alignment="center" css={{ padding: '$2' }}>
                {message}
              </Paragraph>
              <Button
                type="button"
                variant="secondary"
                css={{ margin: '$6 auto 0' }}
                disabled={isHover}
              >
                {buttonIntl ?? DEFAULT_TEXTS.button}
              </Button>
            </>
          )}
        </Container>
      )}
    </Dropzone>
  );
};

export const FileUploader = React.forwardRef(FileUploaderComponent);
export default FileUploader;
